ALTER TABLE public.auctions ADD COLUMN closing_mode text NOT NULL DEFAULT 'fixed' CHECK(closing_mode IN ('fixed','reserve')), ADD COLUMN quiet_period_seconds integer NOT NULL DEFAULT 300 CHECK(quiet_period_seconds BETWEEN 60 AND 86400);
GRANT SELECT(closing_mode,quiet_period_seconds) ON public.auctions TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.auction_bid_deadline(_mode text,_end timestamptz,_now timestamptz,_met boolean,_quiet integer) RETURNS timestamptz LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _mode='reserve' AND _met THEN _now+make_interval(secs=>_quiet) WHEN _mode='fixed' AND _end-_now<=interval '60 seconds' THEN _end+interval '60 seconds' ELSE _end END $$;
CREATE OR REPLACE FUNCTION public.auction_mode_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND OLD.status<>'draft' AND (NEW.closing_mode IS DISTINCT FROM OLD.closing_mode OR NEW.quiet_period_seconds IS DISTINCT FROM OLD.quiet_period_seconds) THEN RAISE EXCEPTION 'La modalidad publicada no puede cambiar'; END IF; IF NEW.closing_mode='reserve' AND (NEW.auction_type<>'item' OR (NEW.status IN ('active','scheduled') AND NOT EXISTS(SELECT 1 FROM public.auction_private p WHERE p.auction_id=NEW.id AND p.reserve_price>0))) THEN RAISE EXCEPTION 'La modalidad por objetivos exige reserva privada de producto'; END IF; RETURN NEW; END $$;
CREATE TRIGGER auction_mode_guard BEFORE INSERT OR UPDATE ON public.auctions FOR EACH ROW EXECUTE FUNCTION public.auction_mode_guard();
CREATE OR REPLACE FUNCTION public.save_extended_draft(_data jsonb,_private jsonb,_delivery jsonb,_request jsonb,_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE draft_id uuid; BEGIN IF _data->>'auction_type'='item' AND _delivery IS NULL THEN RAISE EXCEPTION 'Elige modalidad de entrega'; END IF; IF _data->>'auction_type'='service' AND _request IS NULL THEN RAISE EXCEPTION 'Completa la solicitud de servicio'; END IF; IF coalesce(_data->>'closing_mode','fixed')='reserve' AND (_data->>'auction_type'<>'item' OR coalesce((_private->>'reserve_price')::numeric,0)<=0) THEN RAISE EXCEPTION 'La modalidad por objetivos exige reserva privada'; END IF; draft_id:=public.save_auction_draft(_id,_data||jsonb_build_object('service_from',NULL,'service_to',NULL),_private); UPDATE public.auctions SET closing_mode=coalesce(_data->>'closing_mode','fixed'),quiet_period_seconds=coalesce((_data->>'quiet_period_seconds')::integer,300) WHERE id=draft_id; IF _data->>'auction_type'='item' THEN UPDATE public.auctions SET delivery_snapshot=_delivery,delivery_terms=coalesce(_delivery->>'conditions','') WHERE id=draft_id; ELSE INSERT INTO public.service_requests(auction_id,request) VALUES(draft_id,_request) ON CONFLICT(auction_id) DO UPDATE SET request=excluded.request,updated_at=now(); END IF; RETURN draft_id; END $$;
CREATE OR REPLACE FUNCTION public.place_bid(_auction_id uuid,_amount numeric,_idempotency_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE a public.auctions; existing public.bids; b public.bids; reserve_value numeric; limit_value numeric; ts timestamptz; new_end timestamptz; met_value boolean;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Inicia sesión para ofertar'; END IF;
 IF _idempotency_key IS NULL OR length(_idempotency_key) NOT BETWEEN 8 AND 100 THEN RAISE EXCEPTION 'Solicitud inválida'; END IF;
 IF _amount IS NULL OR _amount<=0 OR _amount>1000000000 OR _amount<>round(_amount,2) THEN RAISE EXCEPTION 'Importe no válido'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':'||_idempotency_key,0));
 SELECT * INTO existing FROM public.bids WHERE bidder_id=auth.uid() AND idempotency_key=_idempotency_key;
 IF existing.id IS NOT NULL THEN IF existing.auction_id<>_auction_id OR existing.amount<>_amount THEN RAISE EXCEPTION 'La solicitud ya se usó para otra oferta'; END IF; RETURN jsonb_build_object('ok',true,'duplicate',true,'bid_id',existing.id); END IF;
 SELECT * INTO a FROM public.auctions WHERE id=_auction_id FOR UPDATE; ts:=clock_timestamp();
 IF a.id IS NULL OR a.status<>'active' OR ts<a.starts_at OR ts>=a.ends_at THEN RAISE EXCEPTION 'La subasta no está activa o ha cerrado'; END IF;
 IF a.seller_id=auth.uid() THEN RAISE EXCEPTION 'No puedes ofertar en tu propia subasta'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') THEN RAISE EXCEPTION 'Cuenta no disponible'; END IF;
 IF a.leader_id=auth.uid() THEN RAISE EXCEPTION 'Ya tienes la oferta líder'; END IF;
 IF a.auction_type='service' THEN
  IF NOT public.has_active_seller_sub(auth.uid()) OR NOT public.has_active_seller_sub(a.seller_id) THEN RAISE EXCEPTION 'Cliente y proveedor necesitan membresía activa'; END IF;
  limit_value:=a.current_price-a.min_increment;
  IF limit_value IS NOT NULL AND _amount>limit_value THEN RAISE EXCEPTION 'Tu oferta debe ser % o menos',limit_value; END IF;
 ELSE
  limit_value:=CASE WHEN a.current_price IS NULL THEN a.starting_price ELSE a.current_price+a.min_increment END;
  IF _amount<limit_value THEN RAISE EXCEPTION 'La oferta mínima es %',limit_value; END IF;
 END IF;
 INSERT INTO public.bids(auction_id,bidder_id,amount,idempotency_key,created_at) VALUES(a.id,auth.uid(),_amount,_idempotency_key,ts) RETURNING * INTO b;
 SELECT reserve_price INTO reserve_value FROM public.auction_private WHERE auction_id=a.id;
 met_value:=a.auction_type='item' AND (reserve_value IS NULL OR b.amount>=reserve_value);
 new_end:=public.auction_bid_deadline(a.closing_mode,a.ends_at,ts,met_value,a.quiet_period_seconds);
 IF new_end<>a.ends_at THEN INSERT INTO public.auction_extensions(auction_id,bid_id,old_ends_at,new_ends_at,reason) VALUES(a.id,b.id,a.ends_at,new_end,CASE WHEN a.closing_mode='reserve' THEN 'Período por reserva reiniciado tras oferta válida' ELSE 'Oferta válida en los últimos 60 segundos' END); END IF;
 PERFORM set_config('nexo.engine','on',true);
 UPDATE public.auctions SET current_price=b.amount,bid_count=bid_count+1,leader_id=auth.uid(),reserve_met=met_value,ends_at=new_end,extensions_count=extensions_count+CASE WHEN new_end<>a.ends_at THEN 1 ELSE 0 END WHERE id=a.id;
 PERFORM set_config('nexo.engine','off',true);
 INSERT INTO public.auction_events(auction_id,kind,details) VALUES(a.id,'bid',jsonb_build_object('bid_id',b.id,'amount',b.amount,'extended',new_end<>a.ends_at));
 IF a.leader_id IS NOT NULL THEN PERFORM public.notify(a.leader_id,'Te han superado','Hay una nueva oferta líder.','/subastas/'||a.id); END IF;
 PERFORM public.notify(auth.uid(),'Oferta aceptada','Tu oferta fue registrada.','/subastas/'||a.id);
 PERFORM public.notify(a.seller_id,'Nueva oferta en NEXO','Se registró una nueva oferta en tu subasta.','/subastas/'||a.id);
 IF new_end<>a.ends_at THEN PERFORM public.notify(a.seller_id,'Cierre actualizado','Una oferta válida actualizó el plazo de cierre.','/subastas/'||a.id); PERFORM public.notify(auth.uid(),'Cierre actualizado','Tu oferta válida actualizó el plazo de cierre.','/subastas/'||a.id); END IF;
 RETURN jsonb_build_object('ok',true,'bid_id',b.id,'ends_at',new_end,'extended',new_end<>a.ends_at,'closing_mode',a.closing_mode);
END $$;
CREATE OR REPLACE VIEW public.auctions_safe WITH(security_barrier=true) AS SELECT a.id,a.seller_id,a.title,a.description,a.category_id,a.country,a.city,a.scope,a.delivery_terms,CASE WHEN a.auction_type='service' THEN ARRAY[]::text[] ELSE a.images END AS images,CASE WHEN a.auction_type='item' THEN a.starting_price ELSE NULL END AS starting_price,a.min_increment,a.currency,a.status,a.duration_hours,a.starts_at,a.ends_at,a.original_ends_at,a.current_price,a.bid_count,a.leader_id,a.winner_id,a.has_reserve,a.reserve_met,a.extensions_count,a.flagged,a.created_at,a.updated_at,a.auction_type,NULL::text AS service_from,NULL::text AS service_to,a.duration_minutes,a.selection_pending,a.accepted_payment_methods,a.delivery_snapshot,a.closing_mode,a.quiet_period_seconds FROM public.auctions a WHERE a.status<>'draft' OR a.seller_id=auth.uid() OR public.is_staff(auth.uid());
CREATE TABLE public.social_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),network text NOT NULL CHECK(network IN ('Facebook','Instagram','TikTok','YouTube','WhatsApp','X','Personalizada')),label text NOT NULL CHECK(length(trim(label)) BETWEEN 1 AND 60),url text NOT NULL CHECK(length(url)<=2048 AND url~'^https://[^/@:[:space:]]+([/?#].*)?$'),active boolean NOT NULL DEFAULT false,sort integer NOT NULL DEFAULT 0 CHECK(sort BETWEEN 0 AND 10000),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.social_links TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.social_links TO authenticated;
GRANT ALL ON public.social_links TO service_role;
ALTER TABLE public.social_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY social_public_read ON public.social_links FOR SELECT TO anon,authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY social_admin_write ON public.social_links FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.social_link_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.admin_audit_log(actor_id,action,target,details) VALUES(auth.uid(),'social_link_'||lower(TG_OP),coalesce(NEW.id,OLD.id)::text,jsonb_build_object('network',coalesce(NEW.network,OLD.network))); RETURN coalesce(NEW,OLD); END $$;
CREATE TRIGGER social_link_audit AFTER INSERT OR UPDATE OR DELETE ON public.social_links FOR EACH ROW EXECUTE FUNCTION public.social_link_audit();
ALTER TABLE public.notification_preferences ADD COLUMN activity boolean NOT NULL DEFAULT true;
CREATE TABLE public.notification_push_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notification_id uuid NOT NULL REFERENCES public.notifications(id),device_id uuid NOT NULL REFERENCES public.push_devices(id),user_id uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed','skipped')),created_at timestamptz NOT NULL DEFAULT now(),claimed_at timestamptz,UNIQUE(notification_id,device_id));
GRANT ALL ON public.notification_push_outbox TO service_role;
ALTER TABLE public.notification_push_outbox ENABLE ROW LEVEL SECURITY;
CREATE INDEX notification_push_pending ON public.notification_push_outbox(created_at) WHERE status='pending';
CREATE OR REPLACE FUNCTION public.enqueue_notification_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.notification_push_outbox(notification_id,device_id,user_id) SELECT NEW.id,d.id,NEW.user_id FROM public.push_devices d JOIN public.notification_preferences p ON p.user_id=d.user_id WHERE d.user_id=NEW.user_id AND d.active AND d.transport='webpush' AND (CASE WHEN NEW.body LIKE '%Nueva subasta en NEXO%' THEN p.new_auctions ELSE p.activity END) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER enqueue_notification_push AFTER INSERT ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.enqueue_notification_push();
CREATE OR REPLACE FUNCTION public.new_auction_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE event_id uuid; pref_row record; category_label text; BEGIN IF NEW.status='active' AND OLD.status IN ('draft','scheduled') THEN INSERT INTO public.auction_push_events(auction_id) VALUES(NEW.id) ON CONFLICT DO NOTHING RETURNING auction_id INTO event_id; IF event_id IS NULL THEN RETURN NEW; END IF; SELECT name INTO category_label FROM public.categories WHERE id=NEW.category_id; FOR pref_row IN SELECT p.user_id FROM public.notification_preferences p WHERE p.new_auctions AND p.user_id<>NEW.seller_id AND (cardinality(p.categories)=0 OR NEW.category_id=ANY(p.categories)) LOOP PERFORM public.notify(pref_row.user_id,NEW.title,coalesce(category_label,'Subasta')||' · Nueva subasta en NEXO','/subastas/'||NEW.id); END LOOP; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.claim_notification_push_batch(_limit integer DEFAULT 20) RETURNS TABLE(queue_id uuid,device_id uuid,subscription jsonb,notification_id uuid,title text,body text,path text,auction_id uuid,category_name text,starting_price numeric,currency text,image_path text) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ WITH candidates AS (SELECT q.id FROM public.notification_push_outbox q JOIN public.notifications n ON n.id=q.notification_id JOIN public.push_devices d ON d.id=q.device_id AND d.user_id=q.user_id AND d.active AND d.transport='webpush' JOIN public.notification_preferences p ON p.user_id=q.user_id WHERE q.status='pending' AND CASE WHEN n.body LIKE '%Nueva subasta en NEXO%' THEN p.new_auctions AND EXISTS(SELECT 1 FROM public.auctions a WHERE n.link='/subastas/'||a.id AND a.status='active' AND (cardinality(p.categories)=0 OR a.category_id=ANY(p.categories))) ELSE p.activity END ORDER BY q.created_at LIMIT least(greatest(_limit,1),20) FOR UPDATE OF q SKIP LOCKED),claimed AS(UPDATE public.notification_push_outbox q SET status='sending',claimed_at=now() FROM candidates c WHERE q.id=c.id RETURNING q.*) SELECT c.id,d.id,d.subscription,n.id,n.title,n.body,n.link,a.id,cat.name,CASE WHEN a.auction_type='item' THEN a.starting_price ELSE NULL END,a.currency,CASE WHEN a.auction_type='item' AND a.status<>'draft' THEN a.images[1] ELSE NULL END FROM claimed c JOIN public.push_devices d ON d.id=c.device_id JOIN public.notifications n ON n.id=c.notification_id LEFT JOIN public.auctions a ON n.link='/subastas/'||a.id LEFT JOIN public.categories cat ON cat.id=a.category_id $$;
REVOKE ALL ON FUNCTION public.claim_notification_push_batch(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_notification_push_batch(integer) TO service_role;
COMMENT ON TABLE public.push_outbox IS 'DEPRECATED for new Web Push events: replaced by notification_push_outbox; legacy records retained without replay';